"""Generate standalone file:// bilingual review screens, no model execution."""
import json,sys,html,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from source.contracts import load,dump,sha
from PIL import Image
E=html.escape

CSS='''
:root{color-scheme:light;--ink:#243443;--muted:#5a6770;--accent:#a34b32;--border:#dddcd5;--paper:#f7f6f2;--white:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Apple SD Gothic Neo","Malgun Gothic",sans-serif;font-size:16px;line-height:1.75;color:var(--ink);background:var(--paper)}*{box-sizing:border-box}body{margin:0}a{color:var(--accent);text-underline-offset:.2em}main{max-width:1120px;margin:auto;padding:32px}header{border-bottom:1px solid var(--border);background:white}header>div{max-width:1120px;margin:auto;padding:14px 32px;display:flex;align-items:center;justify-content:space-between;gap:16px}h1,h2,h3{line-height:1.35;letter-spacing:-.035em}h1{font-size:clamp(1.8rem,4vw,3rem);max-width:850px}h2{font-size:1.6rem}p{max-width:800px}section{margin:40px 0;scroll-margin-top:20px}nav{display:flex;gap:10px 20px;flex-wrap:wrap}button,.button{display:inline-block;border:1px solid var(--accent);border-radius:7px;padding:10px 16px;background:var(--accent);color:white;font:inherit;cursor:pointer;text-decoration:none;min-height:44px}button.secondary,.secondary{background:white;color:var(--accent)}button:disabled{opacity:.45;cursor:default}input,select{font:inherit;max-width:100%;padding:8px;border:1px solid #aaa;border-radius:5px}label{display:block;margin:8px 0}fieldset{border:1px solid var(--border);border-radius:8px;margin:14px 0;padding:16px;min-width:0}legend{font-weight:650}img{max-width:100%;height:auto;display:block;border-radius:7px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{border:1px solid var(--border);border-radius:11px;padding:20px;background:white;min-width:0}.muted,.scope{color:var(--muted);font-size:.9rem}.eyebrow{color:var(--accent);font-size:.8rem;font-weight:700;letter-spacing:.06em}.notice{padding:20px;border-left:4px solid var(--accent);background:white}.table-wrap{max-width:100%;overflow-x:auto}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:10px 12px;text-align:left;border-bottom:1px solid var(--border);white-space:nowrap}pre{background:#fff;padding:15px;overflow:auto;font-size:.85rem;max-width:100%}details{padding:18px;background:white;border:1px solid var(--border);border-radius:8px;margin:15px 0}summary{cursor:pointer;font-weight:650}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.annotation-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px}.annotation-grid img{width:100%}.choices{display:flex;gap:10px;flex-wrap:wrap}.choices label{display:inline-flex;align-items:center;gap:5px}.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:8px;background:white;padding:10px;z-index:100}:focus-visible{outline:3px solid #b55215;outline-offset:4px}html[lang=ko]{word-break:keep-all;overflow-wrap:break-word}.error{color:#913923}footer{padding:32px;border-top:1px solid var(--border)}.thumb-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.thumb-grid img{width:100%}@media(max-width:700px){main{padding:24px 18px}header>div{padding:14px 18px}.grid,.annotation-grid{grid-template-columns:1fr}.thumb-grid{grid-template-columns:repeat(3,minmax(0,1fr))}th,td{padding:8px}h2{font-size:1.4rem}}
'''
VIEW_JS=r'''
const data=JSON.parse(document.getElementById('viewer-data').textContent),lang=document.documentElement.lang;
const el=id=>document.getElementById(id);
function render(){const pid=el('prompt').value,seed=Number(el('seed').value);const p=data.prompts.find(p=>p.prompt_id===pid);el('prompt-text').textContent=lang==='ko'?p.korean_display:p.english;el('input-text').textContent=p.english;
 const rows=data.rows.filter(r=>r.job.prompt_id===pid&&r.job.seed_label===seed).sort((a,b)=>a.job.setting.loops-b.job.setting.loops);
 el('images').innerHTML='';for(const r of rows){const d=document.createElement('article');d.className='card';const h=document.createElement('h3');h.textContent=`L=${r.job.setting.loops} · S=${r.job.setting.steps}`;d.append(h);const a=document.createElement('a');a.href='../'+r.relative_image_path;const i=document.createElement('img');i.src=a.href;i.alt=`${p.english} / L${r.job.setting.loops}, S${r.job.setting.steps}`;a.append(i);d.append(a);const t=document.createElement('p');t.className='scope';t.textContent=`${r.complete_seconds.toFixed(3)} s · ${(r.peak_allocated_bytes/2**30).toFixed(2)} GiB allocated peak`;d.append(t);const q=document.createElement('p');const score=data.quality?.per_image?.[r.job_id];q.textContent=score?(lang==='ko'?`평가 조건 ${(score.fraction*100).toFixed(1)}% 충족 · 전체 ${score.pass?'충족':'미충족'}`:`Constraints ${(score.fraction*100).toFixed(1)}% satisfied · all ${score.pass?'pass':'not pass'}`):(lang==='ko'?'조건 충족: 미평가':'Constraints: not annotated');d.append(q);el('images').append(d)}
 const u=new URL(location);u.searchParams.set('prompt',pid);u.searchParams.set('seed',seed);history.replaceState(null,'',u);el('language').href=`viewer.${lang==='ko'?'en':'ko'}.html${u.search}${u.hash}`;}
const url=new URL(location),p=url.searchParams.get('prompt'),s=url.searchParams.get('seed');if([...el('prompt').options].some(x=>x.value===p))el('prompt').value=p;if([...el('seed').options].some(x=>x.value===s))el('seed').value=s;
el('prompt').addEventListener('change',render);el('seed').addEventListener('change',render);window.addEventListener('hashchange',()=>{const u=new URL(location);el('language').href=`viewer.${lang==='ko'?'en':'ko'}.html${u.search}${u.hash}`});render();
'''
ANN_JS=r'''
const data=JSON.parse(document.getElementById('annotation-data').textContent),lang=document.documentElement.lang;const el=id=>document.getElementById(id);let pos=0,answers={};const key='case012-blind-'+data.rubric_sha256;
try{answers=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(answers))}catch{el('message').textContent=lang==='ko'?'브라우저 저장 실패: JSON을 내보내세요.':'Browser storage failed: export JSON.'}}
function render(){const item=data.items[pos];el('image').src='../'+item.path;el('image').alt=lang==='ko'?'조건을 평가할 생성 이미지':'Generated image to annotate';el('prompt-text').textContent=lang==='ko'?item.korean_display:item.english;el('model-input').textContent=item.english;el('position').textContent=`${pos+1} / ${data.items.length}`;el('constraints').innerHTML='';
for(const c of item.constraints){const f=document.createElement('fieldset'),g=document.createElement('legend');g.textContent=c[lang];f.append(g);const choices=document.createElement('div');choices.className='choices';for(const [v,en,ko] of [['satisfied','Satisfied','충족'],['not_satisfied','Not satisfied','미충족'],['uncertain','Uncertain','판단 불확실']]){const l=document.createElement('label'),r=document.createElement('input');r.type='radio';r.name=c.id;r.value=v;r.checked=answers[item.image_id]?.[c.id]===v;r.addEventListener('change',()=>{(answers[item.image_id]??={})[c.id]=v;save();progress()});l.append(r,document.createTextNode(lang==='ko'?ko:en));choices.append(l)}f.append(choices);el('constraints').append(f)}
el('prev').disabled=pos===0;el('next').disabled=pos===data.items.length-1;progress();}
function progress(){const n=data.items.filter(i=>i.constraints.every(c=>answers[i.image_id]?.[c.id])).length;el('progress').textContent=lang==='ko'?`완료 이미지 ${n}/${data.items.length} · JSON 내보내기를 사용하세요.`:`Complete images ${n}/${data.items.length} · Export JSON to keep a file.`}
el('prev').onclick=()=>{pos--;render()};el('next').onclick=()=>{pos++;render()};el('unrated').onclick=()=>{const n=data.items.findIndex(i=>i.constraints.some(c=>!answers[i.image_id]?.[c.id]));if(n>=0){pos=n;render()}};
el('export').onclick=()=>{const id=el('evaluator').value.trim();if(!id){el('message').textContent=lang==='ko'?'평가자 이름 또는 익명 ID를 입력하세요.':'Enter an evaluator name or anonymous ID.';return}
 const rows=data.items.filter(i=>i.constraints.every(c=>answers[i.image_id]?.[c.id])).map(i=>({image_id:i.image_id,image_sha256:i.image_sha256,values:answers[i.image_id]}));const payload={schema:'case012-annotations-v1',rubric_sha256:data.rubric_sha256,evaluator:{type:'human',id},status:rows.length===data.items.length?'COMPLETE':'PARTIAL',rows,incomplete_image_ids:data.items.filter(i=>!rows.some(r=>r.image_id===i.image_id)).map(i=>i.image_id)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='case012_annotations.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);el('message').textContent=lang==='ko'?'내보냈습니다. 다운로드된 JSON 파일을 보관하세요.':'Exported. Keep the downloaded JSON file.';};
el('import').addEventListener('change',async()=>{try{const f=el('import').files[0];const x=JSON.parse(await f.text());if(x.schema!=='case012-annotations-v1'||x.rubric_sha256!==data.rubric_sha256)throw Error('schema / rubric mismatch');const map=new Map(data.items.map(i=>[i.image_id,i]));const seen=new Set(),next={...answers};for(const r of x.rows){const i=map.get(r.image_id);if(!i||seen.has(r.image_id)||r.image_sha256!==i.image_sha256)throw Error('image identity mismatch');seen.add(r.image_id);if(Object.keys(r.values).sort().join()!==i.constraints.map(c=>c.id).sort().join()||Object.values(r.values).some(v=>!['satisfied','not_satisfied','uncertain'].includes(v)))throw Error('constraint mismatch');next[r.image_id]=r.values}answers=next;el('evaluator').value=x.evaluator?.id||'';save();render();el('message').textContent=lang==='ko'?'JSON을 가져왔습니다.':'Imported JSON.'}catch(e){el('message').textContent=String(e)}});render();
'''

def head(lang,title,kind):
    other='en' if lang=='ko' else 'ko'
    return f'''<!doctype html><html lang="{lang}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · DIOVA</title><link rel="stylesheet" href="style.css"><body><a class="skip" href="#main">{'본문으로' if lang=='ko' else 'Skip to content'}</a><header><div><b>DIOVA · Case 012</b><a id="language" href="{kind}.{other}.html">{'English' if lang=='ko' else '한국어'}</a></div></header><main id="main">'''

def build():
    summary=load(ROOT/'analysis/summary.json');rows=load(ROOT/'analysis/record_index.json')['rows'];ps=load(ROOT/'configs/prompts.json')['prompts'];items=load(ROOT/'analysis/annotation_items.json')
    main=[r for r in rows if r['status']=='SUCCESS' and r['job']['phase']=='main'];smoke=[r for r in rows if r['status']=='SUCCESS' and r['job']['phase']=='smoke']
    dest=ROOT/'demo';(dest/'style.css').write_text(CSS);(dest/'viewer.js').write_text(VIEW_JS);(dest/'annotation.js').write_text(ANN_JS)
    thumbs=dest/'thumbs';thumbs.mkdir(exist_ok=True)
    for r in main+smoke:
        with Image.open(ROOT/r['relative_image_path']) as im:
            im.thumbnail((256,256));im.save(thumbs/(r['job_id']+'.jpg'),quality=90)
    annitems=sorted(items['items'],key=lambda i:i['image_id'])
    # Only opaque image paths, text and constraints reach the annotation script. Pairing/config/time fields stay outside it.
    blind=[{k:i[k] for k in ['image_id','image_sha256','path','english','korean_display','constraints']} for i in annitems]
    dump(dest/'pairing_key.json',{'items':[{k:r[k] for k in ['job_id','job','image_sha256']} for r in main+smoke]})
    for lang in ['ko','en']:
        ko=lang=='ko';title='같은 생성 시간, 어디에 계산을 더 쓸까?' if ko else 'Allocating an Image-Generation Budget: Loops vs Steps'
        labels=['한눈에 보기','Loop와 Step은 무엇인가?','비교 방법','이미지와 결과','시간·메모리','직접 실행','설계·출처'] if ko else ['Overview','What are loops and steps?','Comparison','Images and results','Time and memory','Run and inspect','Design and sources']
        ids=['overview','loops','method','results','cost','reproduce','report']
        intro='같은 모델에서 내부 반복과 생성 단계에 시간을 나눠 쓰는 도구를 구현했습니다. 같은 초기 잡음의 세 이미지를 비교하고, 조건을 가린 화면에서 개수·색·좌우 요구를 평가할 수 있습니다.' if ko else 'Built a runner that allocates time between internal loops and generation steps in one frozen model. Compare three images from identical initial noise, then annotate count, color and left/right constraints in a blinded screen.'
        out=head(lang,title,'viewer')+f'<p class="eyebrow">IMAGE GENERATION · RTX 5080</p><h1>{title}</h1><p>{intro}</p><nav>'+''.join(f'<a href="#{id}">{lab}</a>' for id,lab in zip(ids,labels))+'</nav>'
        out+=f'<section id="overview"><h2>{labels[0]}</h2><div class="notice"><p>{"MAIN 192장 · SMOKE 24장 · 품질 주석 대기" if ko else "192 MAIN images · 24 SMOKE images · Quality annotations pending"}</p><p>{"생성과 측정을 마쳤습니다. 조건 충족 비율과 우수 preset은 사람의 평가 후 계산합니다." if ko else "Generation and timing are complete. Constraint pass rates and quality-based presets await evaluator annotations."}</p></div><div class="actions"><a class="button" href="annotation.{lang}.html">{"조건을 가리고 평가하기" if ko else "Annotate without setting labels"}</a><a href="../source/adapter.py">{"실행 코드" if ko else "Adapter code"}</a></div></section>'
        out+=f'<section id="loops"><h2>{labels[1]}</h2><p>{"Step은 잡음에서 이미지로 이동하는 생성 단계입니다. Loop는 각 단계 안에서 같은 core block을 다시 사용하는 횟수입니다. B/32의 32는 이미지 patch 크기이며 loop 횟수가 아닙니다." if ko else "A step advances the noisy image toward its final form. Loops reuse the same core blocks inside each step. B/32 means a 32-pixel patch size, not 32 loops."}</p><p>{"L=1도 4-loop로 학습된 같은 저장본을 사용합니다. 세 설정 모두 512px, Euler, CFG=6, BF16 denoiser와 FP32 T5를 유지했습니다." if ko else "L=1 uses the same checkpoint trained at four loops. All settings keep 512px, Euler, CFG=6, a BF16 denoiser and FP32 T5."}</p></section>'
        out+=f'<section id="method"><h2>{labels[2]}</h2><p>{"시간 전용 DEV 입력에서 L=4/S=50을 기준으로 가까운 요청 시간을 선택했습니다. 이미지 품질은 설정 선택에 사용하지 않았습니다. MAIN은 16개 prompt × 4개 seed의 같은 64쌍을 세 설정에서 생성했습니다." if ko else "Timing-only DEV requests selected configurations near the L=4/S=50 reference time. Image quality was not used for selection. MAIN generates the same 64 prompt–seed pairs (16 prompts × four seeds) at three settings."}</p><details><summary>{"비용 proxy와 실제 호출 수" if ko else "Block proxy and actual call counts"}</summary><p>CFG=6: model calls = 2S; joint block visits = 2S(12+5L). Proxy A/B/C: 3,196 / 3,212 / 3,200. {"FLOPs나 요청 시간이 같다는 뜻은 아닙니다. Text preamble·embedding·head·T5·전송 비용은 proxy 밖입니다." if ko else "These are not equal FLOPs or latency. Text preamble, embeddings, output heads, T5 and transfers are outside the proxy."}</p><a href="../configs/protocol.json">Protocol</a></details></section>'
        options=''.join(f'<option value="{p["prompt_id"]}">{E(p["korean_display"] if ko else p["english"])}</option>' for p in ps if p['split']=='MAIN')
        seedopts=''.join(f'<option value="{s}">{s}</option>' for s in [72301,72302,72303,72304])
        out+=f'<section id="results"><h2>{labels[3]}</h2><p>{"좋은 이미지만 골라 보여주지 않습니다. 모든 64쌍을 선택할 수 있습니다. 비교 화면을 보기 전에 blind 평가를 진행하면 설정 기대를 줄일 수 있습니다." if ko else "All 64 pairs are available, with no quality selection. Annotate in the blind screen before inspecting setting comparisons to reduce expectation bias."}</p><label>Prompt <select id="prompt">{options}</select></label><label>Seed <select id="seed">{seedopts}</select></label><p id="prompt-text"></p><details><summary>{"실제 영어 입력" if ko else "Actual English model input"}</summary><p id="input-text"></p></details><div class="grid" id="images"></div><noscript><p>{"JS 없이 전체 이미지 목록을 확인할 수 있습니다." if ko else "The full image list is accessible without JavaScript."}</p><a href="gallery.{lang}.html">{"전체 이미지 목록" if ko else "All images"}</a></noscript></section>'
        tr=''
        for id,t in summary['timing'].items():
            tr+=f'<tr><th>{id}</th><td>{t["loops"]}</td><td>{t["steps"]}</td><td>{t["main_complete_median_seconds"]:.3f} s</td><td>{t["main_sampler_gpu_median_ms"]:.1f} ms</td><td>{t["main_peak_allocated_bytes"]/2**30:.3f} GiB</td></tr>'
        out+=f'<section id="cost"><h2>{labels[4]}</h2><div class="table-wrap"><table><thead><tr><th>{"설정" if ko else "Setting"}</th><th>L</th><th>S</th><th>{"요청 median" if ko else "Request median"}</th><th>Sampler GPU</th><th>Allocated peak</th></tr></thead><tbody>{tr}</tbody></table></div><p class="scope">{"각 설정 64개 MAIN 요청. 문자열→T5→sampling→CPU/PIL 변환이며 다운로드·cold load·PNG 저장·평가는 제외합니다. Sampler event는 T5와 초기 잡음 생성을 제외합니다. 장치 전체 사용량과 torch allocated/reserved는 별개입니다." if ko else "64 MAIN requests per setting. String→T5→sampling→CPU/PIL excludes downloads, cold load, PNG writes and evaluation. Sampler events exclude T5 and initial-noise creation. Device-wide usage differs from torch allocated/reserved memory."}</p><details><summary>{"DEV 오차와 세 fresh-process 반복" if ko else "DEV mismatches and three fresh-process repeats"}</summary><pre>{E(json.dumps({'settings':summary['main_settings']['settings'],'repeat_medians':{k:t['repeat_process_medians'] for k,t in summary['timing'].items()}},indent=2))}</pre></details></section>'
        report='REPORT.ko.md' if ko else 'REPORT.md'
        out+=f'<section id="reproduce"><h2>{labels[5]}</h2><p>{"이 화면은 저장된 PNG와 측정 기록을 탐색합니다. 브라우저에서 모델을 실행하지 않습니다." if ko else "This screen explores saved PNGs and measurements. It does not run the model in the browser."}</p><pre>python analysis/analyze.py\npython analysis/audit.py --output audit-receipt.json\npython -m pytest -q tests</pre><div class="actions"><a href="../REPRODUCTION.md">CPU / GPU instructions</a><a href="../source/run.py">Runner</a><a href="../configs/main_settings.json">Measured presets</a></div></section>'
        out+=f'<section id="report"><h2>{labels[6]}</h2><p><a href="../{report}">{"한글 정식 보고서" if ko else "Full English report"}</a> · <a href="../provenance/models.json">Model identity</a> · <a href="../NOTICE.md">Attribution</a></p><p>Looped-DiT: <a href="https://github.com/OpenSenseNova/Looped-DiT">OpenSenseNova</a> · <a href="https://arxiv.org/abs/2609.40305">Paper</a>. DIOVA: {"동일 잡음 runner·시간 선택·주석·결과 탐색 도구." if ko else "paired-noise runner, time selection, annotation and result inspection tools."}</p></section>'
        viewdata={'prompts':[p for p in ps if p['split']=='MAIN'],'rows':main,'quality':summary['quality']}
        out+='</main><script type="application/json" id="viewer-data">'+json.dumps(viewdata,ensure_ascii=False).replace('<','\\u003c')+'</script><script src="viewer.js"></script></body></html>'
        (dest/f'viewer.{lang}.html').write_text(out)
        # Static all-image list supports JS-off and archive review.
        gallery=head(lang,'전체 이미지' if ko else 'All images','gallery')+f'<h1>{"전체 MAIN·SMOKE 이미지" if ko else "All MAIN and SMOKE images"}</h1><a href="viewer.{lang}.html#results">{"비교 화면" if ko else "Comparison viewer"}</a>'
        for r in main+smoke:
            j=r['job'];p=next(p for p in ps if p['prompt_id']==j['prompt_id']);gallery+=f'<article class="card"><h2>{E(j["prompt_id"])} · {j["seed_label"]} · L{j["setting"]["loops"]}/S{j["setting"]["steps"]}</h2><p>{E(p["korean_display"] if ko else p["english"])}</p><a href="../{r["relative_image_path"]}"><img loading="lazy" src="thumbs/{r["job_id"]}.jpg" width="256" height="256" alt="{E(p["english"])}"></a><p>{"256px 썸네일 · 클릭하면 512px 원본" if ko else "256px thumbnail · click for the 512px original"}</p></article>'
        (dest/f'gallery.{lang}.html').write_text(gallery+'</main></body></html>')
        ann=head(lang,'조건을 가린 이미지 평가' if ko else 'Blind image annotation','annotation')
        ann+=f'<h1>{"요청한 조건을 지켰나요?" if ko else "Does this image satisfy the requested constraints?"}</h1><p>{"설정·시간·seed 표시는 없습니다. 개별 이미지를 먼저 판독하고 JSON으로 내보내세요. uncertain은 주 지표에서 미충족으로 계산합니다." if ko else "Settings, time and seed labels are hidden. Judge individual images first and export JSON. Uncertain counts as failure in the primary score."}</p><details><summary>{"평가 규칙" if ko else "Annotation rules"}</summary><p>{"요청한 종류의 모든 물체를 셉니다. 잘려도 식별되면 포함하고, 개수를 확정할 수 없으면 불확실로 표시합니다. 그림자·반사상은 별도 물체로 세지 않습니다. 색은 몸체의 주된 색을 봅니다. 좌우는 이미지 좌표의 물체 중심으로 판단합니다." if ko else "Count all requested object types. Include identifiable cropped objects; use uncertain when counts are ambiguous. Shadows and reflections are not extra objects. Use the main body color and image-coordinate object centers for left/right."}</p><a href="../configs/rubric.json">Frozen rubric</a></details><label>{"평가자 이름 또는 익명 ID" if ko else "Evaluator name or anonymous ID"}<input id="evaluator" autocomplete="off"></label><p id="progress" role="status"></p><p id="position"></p><div class="annotation-grid"><div><img id="image" alt="Generated image to annotate"><p id="prompt-text"></p><details><summary>{"실제 영어 입력" if ko else "Actual English input"}</summary><p id="model-input"></p></details></div><div id="constraints"></div></div><div class="actions"><button id="prev">{"이전" if ko else "Previous"}</button><button id="next">{"다음" if ko else "Next"}</button><button id="unrated" class="secondary">{"미평가로 이동" if ko else "Next unrated"}</button></div><div class="actions"><button id="export">{"JSON 내보내기" if ko else "Export JSON"}</button><label>{"JSON 가져오기" if ko else "Import JSON"}<input id="import" type="file" accept="application/json,.json"></label></div><p id="message" role="alert"></p><p class="scope">{"localStorage는 보조 저장입니다. 내보낸 JSON이 검산 입력이며 이미지 SHA256과 rubric SHA256을 포함합니다. 실제 이미지 바이트는 CPU auditor로 검증합니다." if ko else "localStorage is supplementary. Exported JSON is the analysis input and contains image and rubric SHA256 identities. The CPU auditor checks actual image bytes."}</p><noscript>JavaScript is required for interactive annotation; the frozen rubric and CPU verifier remain available.</noscript></main>'
        ann+='\n<script type="application/json" id="annotation-data">'+json.dumps({'rubric_sha256':items['rubric_sha256'],'items':blind},ensure_ascii=False).replace('<','\\u003c')+'</script><script src="annotation.js"></script></body></html>'
        (dest/f'annotation.{lang}.html').write_text(ann)
    print('Built bilingual viewer and blind annotation, all 216 MAIN/SMOKE images included.')
